const crypto = require('crypto');
const lead = $input.first().json;
const correlationId = String(lead.correlationId || lead.metadata?.correlationId || $execution.id);
const request = {
  clientId: $env.LEADOPS_CLIENT_ID,
  integrationId: $env.LEADOPS_INTEGRATION_ID,
  correlationId,
  requestVersion: '1',
  snapshot: {
    ...(lead.leadId && /^[0-9a-f-]{36}$/i.test(lead.leadId) ? { leadId: lead.leadId } : {}),
    contactName: lead.contactName || null,
    company: lead.company || null,
    message: lead.message || null,
    score: Number.isInteger(lead.qualification?.score) ? lead.qualification.score : null,
    qualificationSummary: lead.qualification?.summary || null,
    qualificationDecision: lead.qualification?.decision || null,
    suggestedNextAction: lead.qualification?.suggestedNextAction || null
  },
  expiresInSeconds: 604800,
  generateToken: true
};
const rawBody = JSON.stringify(request);
const webhookId = `approval-${correlationId}`.replace(/[^a-zA-Z0-9_-]/g, '-').slice(0, 200);
const timestamp = String(Math.floor(Date.now() / 1000));
const secret = $env.LEADOPS_WEBHOOK_SECRET;
if (!secret) throw new Error('LEADOPS_WEBHOOK_SECRET is required');
const encoded = secret.startsWith('whsec_') ? secret.slice(6) : secret;
const signature = crypto.createHmac('sha256', Buffer.from(encoded, 'base64'))
  .update(`${webhookId}.${timestamp}.${rawBody}`).digest('base64');
return [{ json: { rawBody, webhookId, timestamp, signature: `v1,${signature}` } }];

const crypto = require('crypto');
const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || input;
const webhookId = String(headers['webhook-id'] || '');
const timestamp = String(headers['webhook-timestamp'] || '');
const received = String(headers['webhook-signature'] || '');
if (!webhookId || !/^\d{1,12}$/.test(timestamp) || Math.abs(Date.now() - Number(timestamp) * 1000) > 300000) throw new Error('Invalid callback timestamp');
const secret = $env.LEADOPS_WEBHOOK_SECRET;
const encoded = secret.startsWith('whsec_') ? secret.slice(6) : secret;
const rawBody = JSON.stringify(body);
const expected = `v1,${crypto.createHmac('sha256', Buffer.from(encoded, 'base64')).update(`${webhookId}.${timestamp}.${rawBody}`).digest('base64')}`;
const a = Buffer.from(received); const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('Invalid callback signature');
return [{ json: body }];

const approval = $input.first().json;
const approved = approval.status === 'approved';
return [{ json: { approvalId: approval.approvalId, status: approval.status, adapterPlan: approved ? { crm: 'create_deal', calendar: 'schedule_follow_up', email: 'send_approved' } : { crm: 'no_high_risk_action', calendar: 'none', email: 'send_rejected' } } }];
